-- Owner-authorized learner-input feedback for the running new CNN case.
-- Additive and idempotent; existing tasks and prior messages are preserved.
INSERT INTO task_messages (id,job_id,user_id,role,kind,body,attachments,status,created_at,updated_at)
SELECT 'c97aacc8-b76a-4c40-b5b3-73138c3ce8b4',id,user_id,'user','revision','Automated learner-input acceptance feedback: a normal larger-kernel experiment exposes one required scene correction. In cnn-06-sampling, the current v009 source is byte-identical to the reviewed v007 source (SHA256 d8bc27c02d072424a8f6d26b08a627211e301a7f64909a598fee6c575ee204f1). In a real Monaco keyboard edit, changing only k=3 to k=7 with n=5, stride1, padding0, dilation1 and then pressing Run causes a generic runtime fallback: the taps label tries join(state.calc.taps[0],...) although there is no valid first patch. The scene unloads, so its Reset button becomes unavailable. This was one actual edited-source run, not state injection. Please validate meaningful convolution parameters before returning results: positive integer n/k/stride/dilation, nonnegative integer padding, and an effective kernel that fits the padded input. For this invalid experiment, report a clear code error explaining how to adjust kernel/padding while keeping the labeled reference view, editor, error output and Reset usable; do not display negative dimensions or a positive position count from squaring them. Make the taps display tolerate no valid first patch where appropriate. Add a regression for the larger-kernel edit and Reset, and rerun the existing valid stride/padding/dilation checks. Keep the 20-page scope, all other accepted corrections and old versions. This is a small teaching-scene input-validation fix; it does not call for a runtime/plugin change or retraining the CNN.','[]','pending',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000
FROM jobs WHERE id='db69fb9d-5d27-4fc2-9553-a722e2a5acbc' AND status='running' AND user_id=(SELECT user_id FROM jobs WHERE id='2d8c4072-7aee-4f55-8fb0-8f074de4f8cb' AND title='介绍cnn')
AND (SELECT COUNT(*) FROM task_messages WHERE job_id='db69fb9d-5d27-4fc2-9553-a722e2a5acbc')<1000
ON CONFLICT(job_id,id) DO NOTHING;
